#!/usr/bin/env python3
"""Собирает server/battle_demo.json — демонстрационную викторину со всеми типами вопросов.
Картинка для вопросов «подписи» и «область на картинке» составлена из рисунков деталей компьютера (tools/lab/art)."""
import base64, io, json
from pathlib import Path
from PIL import Image, ImageDraw
ROOT = Path(__file__).resolve().parents[2]; ART = ROOT / 'tools/lab/art'
W, H = 640, 400; img = Image.new('RGB', (W, H), (238, 242, 250)); d = ImageDraw.Draw(img)
parts = [('pc_monitor', 160, 110), ('pc_cpu', 480, 110), ('pc_keyboard', 160, 300), ('pc_ram', 480, 300)]
for name, x, y in parts:
    d.rounded_rectangle((x - 140, y - 85, x + 140, y + 85), 18, fill=(255, 255, 255), outline=(200, 208, 225), width=3)
    p = Image.open(ART / f'{name}.webp').convert('RGBA'); p.thumbnail((200, 140)); img.paste(p, (x - p.width // 2, y - p.height // 2), p)
buf = io.BytesIO(); img.save(buf, 'WEBP', quality=82); pic = 'data:image/webp;base64,' + base64.b64encode(buf.getvalue()).decode()
spot = lambda x, y: {'x': round(100 * x / W, 1), 'y': round(100 * y / H, 1)}
qs = [
 {'type': 'slide', 'text': 'Добро пожаловать в демонстрацию! Здесь по одному вопросу каждого типа. Слайд — это страница с объяснением без ответа.', 'time': 20},
 {'type': 'single', 'text': 'Какое устройство обрабатывает данные по программе?', 'options': ['Процессор', 'Монитор', 'Клавиатура', 'Колонки'], 'answer': 0, 'time': 20, 'explain': 'Процессор выполняет команды программы.'},
 {'type': 'multi', 'text': 'Выбери все устройства ввода.', 'options': ['Клавиатура', 'Мышь', 'Принтер', 'Микрофон', 'Монитор'], 'answers': [0, 1, 3], 'time': 30, 'explain': 'Ввод — данные идут в компьютер: клавиатура, мышь, микрофон.'},
 {'type': 'fill', 'text': 'Сколько бит в одном байте? Напиши числом или словом.', 'accepted': ['8', 'восемь'], 'time': 20, 'explain': '1 байт = 8 бит.'},
 {'type': 'math', 'text': 'Сколько килобайт в 3 Мбайт?', 'value': '3072', 'tol': 0, 'unit': 'Кбайт', 'time': 40, 'explain': '1 Мбайт = 1024 Кбайт, 3 · 1024 = 3072.'},
 {'type': 'match', 'text': 'Соедини устройство и его назначение.', 'pairs': [['Процессор', 'обработка'], ['Жёсткий диск', 'долговременное хранение'], ['Монитор', 'вывод изображения'], ['Клавиатура', 'ввод текста']], 'time': 45},
 {'type': 'reorder', 'text': 'Расставь единицы по возрастанию.', 'items': ['бит', 'байт', 'килобайт', 'мегабайт', 'гигабайт'], 'time': 40},
 {'type': 'categorize', 'text': 'Разложи по группам.', 'cats': [{'name': 'Ввод', 'items': ['сканер', 'мышь', 'клавиатура']}, {'name': 'Вывод', 'items': ['принтер', 'колонки', 'монитор']}], 'time': 45},
 {'type': 'dragdrop', 'text': 'Перетащи слова: [[процессор]] обрабатывает данные, а [[память]] хранит их. Изображение показывает [[монитор]].', 'distractors': ['мышь', 'сканер'], 'time': 45},
 {'type': 'dropdown', 'text': 'В 1 байте {{8|16|10}} бит, а в 1 Кбайт — {{1024|1000|100}} байт.', 'time': 40},
 {'type': 'label', 'text': 'Подпиши устройства на картинке.', 'image': pic, 'spots': [{'text': 'монитор', **spot(160, 110)}, {'text': 'процессор', **spot(480, 110)}, {'text': 'клавиатура', **spot(160, 300)}, {'text': 'оперативная память', **spot(480, 300)}], 'time': 60},
 {'type': 'hotspot', 'text': 'Щёлкни по устройству, которое выполняет программы.', 'image': pic, 'spots': [{**spot(480, 110), 'r': 15}], 'time': 30, 'explain': 'Программы выполняет процессор.'},
 {'type': 'graph', 'text': 'Отметь на координатной плоскости точки A(2; 3) и B(−4; 1).', 'points': [[2, 3], [-4, 1]], 'time': 60},
 {'type': 'poll', 'text': 'Опрос: какой тип вопросов понравился больше всего?', 'options': ['Сопоставление', 'Перетаскивание', 'Картинки', 'Координаты'], 'time': 30},
 {'type': 'cloud', 'text': 'Облако слов: одно слово — с чем у тебя ассоциируется информатика?', 'time': 30},
 {'type': 'open', 'text': 'Открытый ответ: зачем компьютеру оперативная память? Ответь своими словами.', 'time': 90},
 {'type': 'draw', 'text': 'Нарисуй схему: устройство ввода → процессор → устройство вывода.', 'time': 90},
]
out = {'title': 'Демонстрация: все типы вопросов', 'grade': 0, 'questions': qs}
(Path(__file__).with_name('server') / 'battle_demo.json').write_text(json.dumps(out, ensure_ascii=False))
print(len(qs), 'вопросов, картинка', len(pic) // 1024, 'КБ')
